        @media (max-width: 640px) {
          inset-inline-end: calc(var(--comment-padding-inline) / 3);
        }
      }
    }
  }

  .comment__author {
    .btn {
      font-weight: inherit;
    }

    @media (max-width: 639px) {
      margin-block-end: calc(var(--block-space-half) / 2);

      h3 {
